        case LEXEME_VARIABLE_DEFAULT:
        case LEXEME_VARIABLE: {
            const char *value;

            value = secure_getenv_len(lexeme->value.value, lexeme->value.len);
            if (lexeme->type == LEXEME_VARIABLE) {
